CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, plan TEXT NOT NULL DEFAULT 'free', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS worlds (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL, genre TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY, world_id TEXT NOT NULL, kind TEXT NOT NULL, title TEXT, source_prompt TEXT NOT NULL, rewritten_prompt TEXT, r2_key TEXT, status TEXT NOT NULL DEFAULT 'queued', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(world_id) REFERENCES worlds(id));
CREATE TABLE IF NOT EXISTS generation_jobs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, world_id TEXT, kind TEXT NOT NULL, plan TEXT NOT NULL, model TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', idempotency_key TEXT NOT NULL UNIQUE, provider_request_id TEXT, error_code TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ledger_entries (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, job_id TEXT, amount_cents INTEGER NOT NULL, type TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS worlds_user_idx ON worlds(user_id);
CREATE INDEX IF NOT EXISTS assets_world_idx ON assets(world_id);
